import React, { useState, useEffect, useRef } from 'react';

const WEDDING_DATE = new Date('2024-01-27T09:00:00');

function Snowflake({ style }) {
  return (
    <div style={{
      position: 'absolute',
      color: 'white',
      fontSize: Math.random() * 10 + 6 + 'px',
      pointerEvents: 'none',
      animation: `snowfall ${Math.random() * 4 + 3}s linear infinite`,
      animationDelay: Math.random() * 5 + 's',
      ...style,
    }}>✦</div>
  );
}

export default function HeroSection({ guestName }) {
  const [countdown, setCountdown] = useState({ hari: 0, jam: 0, menit: 0, detik: 0 });
  const [visible, setVisible] = useState(false);

  useEffect(() => {
    setVisible(true);
    const tick = () => {
      const now = new Date();
      const diff = WEDDING_DATE - now;
      if (diff > 0) {
        setCountdown({
          hari: Math.floor(diff / (1000 * 60 * 60 * 24)),
          jam: Math.floor((diff / (1000 * 60 * 60)) % 24),
          menit: Math.floor((diff / (1000 * 60)) % 60),
          detik: Math.floor((diff / 1000) % 60),
        });
      } else {
        setCountdown({ hari: 0, jam: 0, menit: 0, detik: 0 });
      }
    };
    tick();
    const id = setInterval(tick, 1000);
    return () => clearInterval(id);
  }, []);

  const snowflakes = Array.from({ length: 30 }, (_, i) => ({
    id: i,
    left: Math.random() * 100 + '%',
    top: Math.random() * 100 + '%',
    delay: Math.random() * 5,
    size: Math.random() * 12 + 6,
  }));

  return (
    <section id="pembuka-section" style={{
      position: 'relative',
      minHeight: '100vh',
      display: 'flex',
      alignItems: 'center',
      justifyContent: 'center',
      overflow: 'hidden',
      background: 'linear-gradient(135deg, #f8c8d8 0%, #e8a0c0 40%, #d070a8 100%)',
    }}>
      <style>{`
        @keyframes snowfall {
          0% { transform: translateY(-20px) rotate(0deg); opacity: 1; }
          100% { transform: translateY(100vh) rotate(360deg); opacity: 0.3; }
        }
        @keyframes heroFadeUp {
          from { opacity: 0; transform: translateY(30px); }
          to { opacity: 1; transform: translateY(0); }
        }
        @keyframes countNum {
          0%, 100% { transform: scale(1); }
          50% { transform: scale(1.15); }
        }
        .hero-content-in { animation: heroFadeUp 1s ease forwards; }
        .hero-delay1 { animation-delay: 0.2s; opacity: 0; }
        .hero-delay2 { animation-delay: 0.4s; opacity: 0; }
        .hero-delay3 { animation-delay: 0.6s; opacity: 0; }
        .hero-delay4 { animation-delay: 0.8s; opacity: 0; }
        .hero-delay5 { animation-delay: 1s; opacity: 0; }
        .count-num { animation: countNum 1s ease infinite; }
        .open-btn:hover { transform: scale(1.05); background: linear-gradient(135deg, #fff, #f8e8f0) !important; }
        .open-btn { transition: transform 0.2s, box-shadow 0.2s !important; }
        .open-btn:hover { box-shadow: 0 8px 30px rgba(233,30,140,0.3) !important; }
      `}</style>

      {/* Background couple image placeholder - pink overlay */}
      <div style={{
        position: 'absolute', inset: 0,
        background: 'url("https://i.imgur.com/placeholder.png") center/cover no-repeat',
        zIndex: 0,
      }} />

      {/* Snowflakes */}
      {snowflakes.map(s => (
        <div key={s.id} style={{
          position: 'absolute',
          left: s.left,
          top: s.top,
          color: 'rgba(255,255,255,0.8)',
          fontSize: s.size + 'px',
          pointerEvents: 'none',
          animation: `snowfall ${Math.random() * 4 + 3}s linear infinite`,
          animationDelay: s.delay + 's',
          zIndex: 1,
        }}>✦</div>
      ))}

      {/* Content */}
      <div style={{
        position: 'relative', zIndex: 2,
        textAlign: 'center',
        color: 'white',
        padding: '40px 20px',
      }}>
        {/* Guest greeting */}
        <p className="hero-content-in hero-delay1" style={{
          fontFamily: "'Poppins', sans-serif",
          fontSize: '1.1rem',
          fontWeight: 400,
          marginBottom: '12px',
          textShadow: '0 2px 8px rgba(0,0,0,0.3)',
          letterSpacing: '0.05em',
        }}>
          Kepada {guestName},
        </p>

        {/* Couple names */}
        <h1 className="hero-content-in hero-delay2" style={{
          fontFamily: "'Dancing Script', cursive",
          fontSize: 'clamp(2.5rem, 8vw, 4.5rem)',
          marginBottom: '20px',
          textShadow: '0 2px 12px rgba(0,0,0,0.25)',
          lineHeight: 1.1,
        }}>
          Armita &amp; Febri
        </h1>

        {/* Announcement text */}
        <p className="hero-content-in hero-delay3" style={{
          fontFamily: "'Poppins', sans-serif",
          fontSize: 'clamp(0.8rem, 2.5vw, 1rem)',
          marginBottom: '8px',
          textShadow: '0 2px 8px rgba(0,0,0,0.3)',
          letterSpacing: '0.05em',
          fontWeight: 300,
        }}>
          Akan segera melangsungkan pernikahan pada tanggal
        </p>

        {/* Wedding date */}
        <p className="hero-content-in hero-delay3" style={{
          fontFamily: "'Poppins', sans-serif",
          fontSize: 'clamp(1rem, 3vw, 1.3rem)',
          fontWeight: 700,
          marginBottom: '30px',
          textShadow: '0 2px 8px rgba(0,0,0,0.3)',
        }}>
          Sabtu, 27 Januari 2024
        </p>

        {/* Countdown */}
        <div className="hero-content-in hero-delay4" style={{
          display: 'flex',
          gap: '20px',
          justifyContent: 'center',
          marginBottom: '40px',
        }}>
          {[
            { val: countdown.hari, label: 'Hari' },
            { val: countdown.jam, label: 'Jam' },
            { val: countdown.menit, label: 'Menit' },
            { val: countdown.detik, label: 'Detik' },
          ].map(({ val, label }) => (
            <div key={label} style={{ textAlign: 'center', minWidth: '50px' }}>
              <div className="count-num" style={{
                fontFamily: "'Poppins', sans-serif",
                fontSize: 'clamp(1.5rem, 5vw, 2.2rem)',
                fontWeight: 600,
                textShadow: '0 2px 8px rgba(0,0,0,0.3)',
                lineHeight: 1,
              }}>
                {String(val).padStart(2, '0')}
              </div>
              <div style={{
                fontFamily: "'Poppins', sans-serif",
                fontSize: '0.8rem',
                fontWeight: 300,
                opacity: 0.9,
                marginTop: '4px',
              }}>
                {label}
              </div>
            </div>
          ))}
        </div>

        {/* Open button */}
        <div className="hero-content-in hero-delay5">
          <button
            className="open-btn"
            onClick={() => {
              document.getElementById('pembuka-section').scrollIntoView({ behavior: 'smooth' });
            }}
            style={{
              background: 'white',
              color: '#e91e8c',
              border: '2px solid white',
              borderRadius: '50px',
              padding: '14px 40px',
              fontSize: '0.9rem',
              fontWeight: 600,
              fontFamily: "'Poppins', sans-serif",
              cursor: 'pointer',
              letterSpacing: '0.1em',
              display: 'flex',
              alignItems: 'center',
              gap: '10px',
              margin: '0 auto',
            }}
          >
            <span>📖</span> BUKA UNDANGAN
          </button>
        </div>
      </div>
    </section>
  );
}
